def build(out_dir: str):
    os.makedirs(out_dir, exist_ok=True)
    for k, lang in enumerate(LANGS):
        d = {row[0]: row[k + 1] for row in T if row[k + 1]}
        with open(os.path.join(out_dir, lang + ".js"), "w", encoding="utf-8") as f:
            f.write("// generated from psptool/ui/i18n_table.py: edit there\n")
            f.write("Object.assign(I18N.dict, %s);\n" % json.dumps(d, ensure_ascii=False, indent=0))


if __name__ == "__main__":
    build(os.path.join(os.path.dirname(os.path.abspath(__file__)), "static", "i18n"))
